def media(scene,key='main',cls='desktop',start=0,dur=None,label=None):
    row=MEDIA.get(f'{scene:02}',{}).get(key)
    if not row: return f'<div class="media-box {cls}"><div class="note">Capture pending: {scene:02}/{esc(key)}</div></div>'
    src=row['path']; duration=dur or DUR[scene-1]-start
    if src.endswith(('.mp4','.webm')):
        tag=f'<video id="s{scene:02}-{key}-video" class="clip" src="{src}" muted playsinline data-start="{start}" data-duration="{duration}" data-track-index="1" data-media-start="{row.get("offset",0)}" data-playback-rate="{row.get("rate",1)}"></video>'
    else: tag=f'<img src="{src}" alt="Recorded AgriClimate application view" />'
    return f'<div class="media-box {cls}" id="s{scene:02}-{key}-box"><div class="camera">{tag}</div>'+ (f'<span class="media-label">{esc(label)}</span>' if label else '')+'</div>'

def term(title,cmd,outs,style=''):
    # Adapted from installed code-terminal-run: stable token panel + timed output cues.
    return f'<div class="terminal" style="{style}"><div class="terminal-bar"><span>{title}</span><span>LOCAL / EVIDENCE</span></div><div class="terminal-content"><span class="cmd">$ {esc(cmd)}</span>'+''.join(f'<span class="out">{esc(o)}</span>' for o in outs)+'</div></div>'

def step(n,title,body=''):
    return f'<div class="step"><span class="num">{n:02}</span><div><h3>{title}</h3>'+ (f'<p>{body}</p>' if body else '')+'</div></div>'

def met(value,label,unit=''):
    return f'<div class="metric"><div class="value">{value}<small>{unit}</small></div><div class="label">{label}</div></div>'

