bodies[14]=f'''<div class="stack" style="width:1090px;gap:30px">{term('vitest / unedited tally','pnpm test',tally or ['Test evidence pending.'])}<div class="swatches"><div class="swatch" style="background:oklch(0.55 0.19 28)">Danger</div><div class="swatch" style="background:#886716">Warning</div><div class="swatch" style="background:#277042">Success</div></div><p class="mono muted" style="font-size:23px">Danger token: oklch(0.55 0.19 28)</p><div class="note">Two failing assertions still expect older UI labels. The failures stay visible.</div><div class="badge-row"><span class="tag">VOICE ENDPOINT: 501</span><span class="tag">NOT IMPLEMENTED</span></div></div><div class="stack" style="flex:1;align-items:center">{media(14,cls='phone large')}<div class="captionlabel">320 px / real UI</div></div>'''
#15 setup instructions not falsely claimed live terminal
bodies[15]=f'''<div class="stack" style="width:1140px;gap:32px"><div class="statement" style="font-size:78px;max-width:1070px">Somebody might as well translate.</div><div class="terminal"><div class="terminal-bar"><span>agriclimate / get started</span><span>SETUP COMMANDS</span></div><div class="terminal-content" style="font-size:30px;line-height:1.9"><span class="cmd" id="s15-line1">$ git clone https://github.com/kynatians/agriclimate.git</span><span class="cmd" id="s15-line2">$ cd agriclimate &amp;&amp; pnpm install</span><span class="cmd" id="s15-line3">$ pnpm dev</span><span class="out">  → http://localhost:3000</span></div></div><div class="badge-row"><span class="tag">NO API KEYS FOR SEED MODE</span><span class="tag">FIRMS KEY FOR LIVE FIRE DATA</span></div><div class="mono green" style="font-size:30px">github.com/kynatians/agriclimate</div><div class="mono muted" style="font-size:24px">12 blocks · 4,245 farmer records · 20 crops · 2 languages</div></div><div class="stack" style="flex:1;align-items:center">{media(15,cls='phone large')}</div>'''
animations[15]='''['#s15-line1','#s15-line2','#s15-line3'].forEach((s,i)=>{const el=document.querySelector(s),text=el.textContent,driver={n:0};tl.fromTo(driver,{n:0},{n:text.length,duration:1.6,ease:'none',immediateRender:false,onUpdate:()=>el.textContent=text.slice(0,Math.floor(driver.n))},.6+i*2.3)});'''
# Write modular sources. Component frames are local to their scene timeline.
(P/'compositions').mkdir(exist_ok=True)
starts=[]; clock=0
story=['# AgriClimate — production storyboard','', '15 scenes · 1920×1080 · 30 fps · 246 seconds', '', 'Concept: evidence becomes action. Long holds on records, hard cuts between human roles.','']
for i,(dur,title,act,source) in enumerate(zip(DUR,TITLES,ACTS,SOURCES),1):
    starts.append(clock)
    id=f's{i:02}'
    dark=i in (1,4,5,12,13,15)
    specific='''
.maphero{width:880px;height:500px}.splitdesktop{width:1310px;height:555px}.splitdesktop img,.splitdesktop video{object-fit:contain}.firedesktop{width:1040px;height:585px}.cropdesktop{width:1110px;height:730px}.loopdesktop{width:1180px;height:744px}.irrigationdesktop{width:1040px;height:365px}
'''
    if i==4:specific+=' .step{padding:10px 0;gap:16px}.step h3{font-size:28px}.step p{font-size:20px;margin-top:4px}'
    if i==11:specific+=' .step{padding:12px 0}.step h3{font-size:29px}.step p{font-size:23px}.terminal-content{font-size:25px;line-height:1.4;padding:20px 26px}'
    if i==10:specific+=' .step{padding:14px 0}.step h3{font-size:29px}.step p{font-size:23px}'
    if i==13:specific+=' .terminal-content{font-size:22px;line-height:1.4;padding:20px 28px}.terminal-bar{height:45px}.node p{font-size:22px}.node h3{font-size:30px}'
    src=f'compositions/{id}.html'
    selected_css=css if dark else re.sub(r'#ROOT\.dark\{[^}]+\}', '', css)
    style=selected_css.replace('#ROOT.dark','#ROOT').replace('#ROOT',f'#{id}')+specific
    body=f'''<div class="rail"><span class="brand">AgriClimate</span><span class="act">{act}</span><span class="mono">{i:02} / 15</span></div><h1 class="heading">{title}</h1><div class="body">{bodies[i]}</div><div class="foot"><span class="receipt">{source}</span><span>{clock//60:02}:{clock%60:02}</span></div>'''
    motion='''const tl=gsap.timeline({paused:true});tl.fromTo('.heading',{x:24,opacity:0},{x:0,opacity:1,duration:.5,ease:'power3.out'},.1);tl.fromTo('.body',{opacity:0},{opacity:1,duration:.35,ease:'power2.out'},.08);tl.fromTo('.rail',{opacity:.5},{opacity:1,duration:.45},0);'''
    if i in (6,8,10,11):
        motion+="tl.fromTo('.step',{y:18,opacity:0},{y:0,opacity:1,duration:.4,stagger:.13,ease:'power2.out'},.5);"
    if i==8:
        motion+="document.querySelectorAll('.step').forEach((el,k)=>tl.fromTo(el,{opacity:.35},{opacity:1,duration:.3,immediateRender:false},1+k*3.1));"
    if i==9:
        motion+="document.querySelectorAll('.barfill').forEach((el,k)=>tl.fromTo(el,{scaleX:0},{scaleX:parseFloat(el.dataset.fill),duration:1.1,ease:'power2.out'},2+k*.35));"
    if i in (3,9):
        motion+="tl.fromTo('.camera',{scale:1,x:0,y:0},{scale:1.045,x:0,y:0,duration:5,ease:'sine.inOut'},6);"
    motion+=animations.get(i,'')
    # Fine-grained terminal output reveal based on registry component's output cues.
    if i in (5,11,14): motion+="tl.fromTo('.terminal .out',{opacity:0},{opacity:1,duration:.15,stagger:.3},1.3);"
    motion+=f'window.__timelines["{id}"]=tl;'
    document=f'<!doctype html><html><head><meta charset="utf-8"></head><body><template><style>{style}</style><div id="{id}" data-composition-id="{id}" data-duration="{dur}" data-width="1920" data-height="1080">{body}</div><script>{motion}</script></template></body></html>'
    (P/src).write_text(document)
    (P/f'compositions/{id}.motion.json').write_text(json.dumps({'duration':dur,'assertions':[{'kind':'appearsBy','selector':f'#{id} .heading','bySec':.8},{'kind':'staysInFrame','selector':f'#{id} .heading'}]},indent=2))
    story += [f'## Frame {i}',f'- status: animated',f'- src: {src}',f'- start: {clock}',f'- duration: {dur}',f'- beat: {title}',f'- narrativeRole: {act}',f'- rules: viewport-change, discrete-text-sequence, stat-bars-and-fills',f'- source: {source}','- capture: real local application where available; engineering annotations are source-grounded.','']
    clock+=dur
(P/'STORYBOARD.md').write_text('\n'.join(story))
# Master root, one scene lane, one voice lane, one bed, one SFX lane.
mounts=[]
for i,(start,dur) in enumerate(zip(starts,DUR),1):
    mounts.append(f'<div id="mount-s{i:02}" class="clip" data-composition-id="s{i:02}" data-composition-src="compositions/s{i:02}.html" data-start="{start}" data-duration="{dur}" data-track-index="0" data-width="1920" data-height="1080"></div>')
voices=[]
for i,(start,dur) in enumerate(zip(starts,DUR),1):
    path=f'assets/voice/scene-{i:02}.wav'
    if (P/path).exists():
        import wave
        with wave.open(str(P/path)) as f: vd=f.getnframes()/f.getframerate()
        offset=.4
        voices.append(f'<audio id="vo-{i:02}" src="{path}" data-audio-group="voiceover" data-label="Narration {i:02}" data-start="{start+offset}" data-duration="{vd:.4f}" data-track-index="2" data-volume="0.95"></audio>')
sfx=[]
for n,t in enumerate([14.85,19.55,32,42,44,46,48,50,52,54,56,77.65,87.1,109,112,115,118,126.6,150.95,154,157,161.5,164.5,168.5,222,226]):
    sfx.append(f'<audio id="sfx-tick-{n}" src=".media/audio/sfx/sfx_001.mp3" data-audio-group="sfx" data-start="{t}" data-duration="0.4" data-track-index="4" data-volume="0.20"></audio>')
sfx.append('<audio id="sfx-notification" src=".media/audio/sfx/sfx_002.mp3" data-audio-group="sfx" data-start="92" data-duration="2.5" data-track-index="4" data-volume="0.45"></audio>')
# Wipes are the installed directional-wipe primitive reduced to the palette's solid cover.
wipes=''
for t in [26,60,126,168,182,218]:
    wipes+=f"tl.fromTo('#wipe',{{x:-1920}},{{x:0,duration:.22,ease:'power3.in'}},{t-.22});tl.to('#wipe',{{x:1920,duration:.28,ease:'power3.out'}},{t});"
master=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><title>AgriClimate — Field Operations</title><script src="assets/gsap.min.js"></script><style>html,body{{margin:0;width:100%;height:100%;overflow:hidden;background:#101f1b}}#agriclimate{{position:relative;width:100%;height:100%;overflow:hidden}}.clip{{position:absolute;inset:0}}#progress{{position:absolute;left:0;bottom:0;height:5px;width:100%;background:#abd4a5;transform-origin:left;z-index:30}}#wipe{{position:absolute;inset:0;background:#23643c;z-index:40;pointer-events:none}}</style></head><body><div id="agriclimate" data-composition-id="agriclimate" data-duration="246" data-width="1920" data-height="1080" data-fps="30">{''.join(mounts)}{''.join(voices)}<audio id="music-bed" src="assets/audio/field-operations-bed.wav" data-audio-group="music" data-label="Original 80 BPM field-ops bed" data-start="0" data-duration="246" data-track-index="3" data-volume="0.65"></audio>{''.join(sfx)}<div id="progress" data-layout-ignore></div><div id="wipe" data-layout-ignore></div></div><script>const tl=gsap.timeline({{paused:true}});tl.fromTo('#progress',{{scaleX:0}},{{scaleX:1,duration:246,ease:'none'}},0);tl.set('#wipe',{{x:-1920}},0);{wipes}window.__timelines['agriclimate']=tl;</script></body></html>'''
(P/'index.html').write_text(master)
(P/'timeline.json').write_text(json.dumps([{'id':f's{i:02}','start':s,'duration':d,'title':t} for i,(s,d,t) in enumerate(zip(starts,DUR,TITLES),1)],indent=2))
print(f'Built 15 scenes / {clock}s, {len(voices)} narration tracks')
